unsafe fn aptx_process_subband(
    mut invert_quantize: *mut aptx_invert_quantize,
    mut prediction: *mut aptx_prediction,
    mut quantized_sample: int32_t,
    mut dither: int32_t,
    mut tables: *const aptx_tables,
) {
    aptx_invert_quantization(invert_quantize, quantized_sample, dither, tables);

    let pred = unsafe { &mut *prediction }; // SAFETY: caller provides a valid mutable pointer to aptx_prediction for the duration of this function.
    let iq = unsafe { &*invert_quantize }; // SAFETY: caller provides a valid pointer to aptx_invert_quantize; aptx_invert_quantization has initialized/updated its fields before this read.
    let tables_view = unsafe { &*tables }; // SAFETY: caller provides a valid pointer to aptx_tables for the duration of this function.

    let reconstructed_difference = iq.reconstructed_difference;
    let predicted_difference = pred.predicted_difference;

    let sign =
        ((reconstructed_difference > -predicted_difference) as c_int
            - (reconstructed_difference < -predicted_difference) as c_int) as int32_t;

    let prev_sign0 = pred.prev_sign[0];
    let prev_sign1 = pred.prev_sign[1];
    let same_sign0 = sign * prev_sign0;
    let same_sign1 = sign * prev_sign1;

    pred.prev_sign[0] = prev_sign1;
    pred.prev_sign[1] = sign | 1 as int32_t;

    let s_weight1 = pred.s_weight[1];
    let mut sw1 = rshift32(-same_sign1 * s_weight1, 1 as c_uint);
    sw1 = (clip(sw1, -(0x100000 as int32_t), 0x100000 as int32_t) & !(0xf as int32_t))
        * 16 as int32_t;

    let s_weight0 = pred.s_weight[0];
    let weight0 =
        254 as int32_t * s_weight0 + 0x800000 as int32_t * same_sign0 + sw1;
    pred.s_weight[0] = clip(
        rshift32(weight0, 8 as c_uint),
        -(0x300000 as int32_t),
        0x300000 as int32_t,
    );

    let range1 = 0x3c0000 as int32_t - pred.s_weight[0];
    let weight1 =
        255 as int32_t * s_weight1 + 0xc00000 as int32_t * same_sign1;
    pred.s_weight[1] = clip(
        rshift32(weight1, 8 as c_uint),
        -range1,
        range1,
    );

    aptx_prediction_filtering(
        prediction,
        reconstructed_difference,
        tables_view.prediction_order,
    );
}

